def _parse_rows() -> tuple[dict[str, str], ...]:
    rows: list[dict[str, str]] = []
    for line in _RAW_ROWS.strip().splitlines():
        values = line.split("|")
        if len(values) != len(_FIELDS):
            raise RuntimeError("invalid_v2_coverage_manifest")
        rows.append(dict(zip(_FIELDS, values, strict=True)))
    return tuple(rows)


COVERAGE_MANIFEST: Final = _parse_rows()
